"""Migrated Meridian CRM credit-hold release guard."""

from __future__ import annotations


class BusinessRuleViolation(Exception):
    """Raised when a migrated legacy business rule blocks an operation."""

    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _legacy_number(value: object) -> float:
    """Apply legacy numeric coercion: missing or empty values become zero."""
    if value is None or value == "":
        return 0.0
    return float(value)


def release_credit_hold(account: dict) -> tuple[dict, list[dict]]:
    """Release an account credit hold, enforcing legacy rule ACC-004."""
    updated_account = dict(account)

    if account.get("CRED_HOLD", "") != "Y":
        return updated_account, []

    if _legacy_number(account.get("CRED_LIMIT", "")) <= 0:
        raise BusinessRuleViolation(
            code="E1004",
            message="Cannot release credit hold with zero credit limit",
        )

    updated_account["CRED_HOLD"] = "N"
    audits = [{
        "code": "CRED_HOLD_OFF",
        "entity_id": account.get("ACCT_ID", ""),
    }]
    return updated_account, audits
